+    const uint32_t* a = reinterpret_cast<const uint32_t*>(&frag_a);
+    const uint32_t* b = reinterpret_cast<const uint32_t*>(&frag_b);
+    float* c = reinterpret_cast<float*>(&frag_c);
+    const float* d = reinterpret_cast<const float*>(&frag_c);
+
+    asm volatile
